141	static __always_inline int
142	handle_ipv6(struct __ctx_buff *ctx, __u32 secctx __maybe_unused,
143		    __u32 ipcache_srcid __maybe_unused,
144		    const bool from_host __maybe_unused,
145		    bool *punt_to_stack __maybe_unused,
146		    __s8 *ext_err __maybe_unused)
147	{
148	#ifdef ENABLE_HOST_FIREWALL
149		struct ct_buffer6 ct_buffer = {};
150		bool need_hostfw = false;
151		bool is_host_id = false;
152	#endif /* ENABLE_HOST_FIREWALL */
153		void *data, *data_end;
154		struct ipv6hdr *ip6;
155		int ret;
156	
157		if (!revalidate_data(ctx, &data, &data_end, &ip6))
158			return DROP_INVALID;
159	
160		if (is_defined(ENABLE_HOST_FIREWALL) || !from_host) {
161			__u8 nexthdr = ip6->nexthdr;
162			int hdrlen;
163	
164			hdrlen = ipv6_hdrlen(ctx, &nexthdr);
165			if (hdrlen < 0)
166				return hdrlen;
167	
168			if (likely(nexthdr == IPPROTO_ICMPV6)) {
169				ret = icmp6_host_handle(ctx, ETH_HLEN + hdrlen, ext_err, !from_host);
170				if (ret == SKIP_HOST_FIREWALL)
171					goto skip_host_firewall;
172				if (IS_ERR(ret))
173					return ret;
174			}
175		}
176	
177	#ifdef ENABLE_NODEPORT
178		if (!from_host) {
179			if (!ctx_skip_nodeport(ctx)) {
180				bool is_dsr = false;
181	
182				ret = nodeport_lb6(ctx, ip6, secctx, punt_to_stack, ext_err, &is_dsr);
183				/* nodeport_lb6() returns with TC_ACT_REDIRECT for
184				 * traffic to L7 LB. Policy enforcement needs to take
185				 * place after L7 LB has processed the packet, so we
186				 * return to stack immediately here with
187				 * TC_ACT_REDIRECT.
188				 */
189				if (ret < 0 || ret == TC_ACT_REDIRECT)
190					return ret;
191				if (*punt_to_stack)
192					return ret;
193			}
194		}
195	#endif /* ENABLE_NODEPORT */
196	
197	#ifdef ENABLE_HOST_FIREWALL
198		if (from_host) {
199			if (ipv6_host_policy_egress_lookup(ctx, secctx, ipcache_srcid, ip6, &ct_buffer)) {
200				if (unlikely(ct_buffer.ret < 0))
201					return ct_buffer.ret;
202				need_hostfw = true;
203				is_host_id = secctx == HOST_ID;
204			}
205		} else if (!ctx_skip_host_fw(ctx)) {
206			/* Verifier workaround: R5 invalid mem access 'scalar'. */
207			if (!revalidate_data(ctx, &data, &data_end, &ip6))
208				return DROP_INVALID;
209	
210			if (ipv6_host_policy_ingress_lookup(ctx, ip6, &ct_buffer)) {
211				if (unlikely(ct_buffer.ret < 0))
212					return ct_buffer.ret;
213				need_hostfw = true;
214			}
215		}
216		if (need_hostfw) {
217			__u32 zero = 0;
218	
219			if (map_update_elem(&cilium_tail_call_buffer6, &zero, &ct_buffer, 0) < 0)
220				return DROP_INVALID_TC_BUFFER;
221		}
222	#endif /* ENABLE_HOST_FIREWALL */
223	
224	skip_host_firewall:
225	#ifdef ENABLE_HOST_FIREWALL
226		ctx_store_meta(ctx, CB_FROM_HOST,
227			       (need_hostfw ? FROM_HOST_FLAG_NEED_HOSTFW : 0) |
228			       (is_host_id ? FROM_HOST_FLAG_HOST_ID : 0));
229	#endif /* ENABLE_HOST_FIREWALL */
230	
231		return CTX_ACT_OK;
232	}
