234	static __always_inline int
235	handle_ipv6_cont(struct __ctx_buff *ctx, __u32 secctx, const bool from_host,
236			 __s8 *ext_err __maybe_unused)
237	{
238		struct trace_ctx __maybe_unused trace = {
239			.reason = TRACE_REASON_UNKNOWN,
240			.monitor = TRACE_PAYLOAD_LEN,
241		};
242		__u32 __maybe_unused from_host_raw;
243		void *data, *data_end;
244		struct ipv6hdr *ip6;
245		union v6addr *dst;
246		int l3_off = ETH_HLEN;
247		struct remote_endpoint_info *info = NULL;
248		struct endpoint_info *ep;
249		int ret __maybe_unused;
250		__u8 encrypt_key __maybe_unused = 0;
251		__u32 magic = MARK_MAGIC_IDENTITY;
252		bool from_proxy = false;
253	
254		if (from_host && tc_index_from_ingress_proxy(ctx)) {
255			from_proxy = true;
256			magic = MARK_MAGIC_PROXY_INGRESS;
257		}
258		if (from_host && tc_index_from_egress_proxy(ctx)) {
259			from_proxy = true;
260			magic = MARK_MAGIC_PROXY_EGRESS;
261		}
262	
263		if (!revalidate_data(ctx, &data, &data_end, &ip6))
264			return DROP_INVALID;
265	
266	#ifdef ENABLE_HOST_FIREWALL
267		from_host_raw = ctx_load_and_clear_meta(ctx, CB_FROM_HOST);
268	
269		if (from_host_raw & FROM_HOST_FLAG_NEED_HOSTFW) {
270			struct ct_buffer6 *ct_buffer;
271			__u32 zero = 0;
272			__u32 remote_id = WORLD_IPV6_ID;
273	
274			ct_buffer = map_lookup_elem(&cilium_tail_call_buffer6, &zero);
275			if (!ct_buffer)
276				return DROP_INVALID_TC_BUFFER;
277			if (ct_buffer->tuple.saddr.d1 == 0 && ct_buffer->tuple.saddr.d2 == 0)
278				/* The map value is zeroed so the map update didn't happen somehow. */
279				return DROP_INVALID_TC_BUFFER;
280	
281			if (from_host) {
282				bool is_host_id = from_host_raw & FROM_HOST_FLAG_HOST_ID;
283	
284				ret = __ipv6_host_policy_egress(ctx, is_host_id, ip6, ct_buffer, &trace,
285								ext_err);
286			} else {
287				ret = __ipv6_host_policy_ingress(ctx, ip6, ct_buffer, &remote_id, &trace,
288								 ext_err);
289			}
290			if (IS_ERR(ret) || ret == CTX_ACT_REDIRECT)
291				return ret;
292	
293			if (from_host) {
294				if (!revalidate_data(ctx, &data, &data_end, &ip6))
295					return DROP_INVALID;
296			}
297		}
298	#endif /* ENABLE_HOST_FIREWALL */
