309		if (!from_host) {
310			if (is_srv6_packet(ip6) && srv6_lookup_sid(&ip6->daddr)) {
311				/* This packet is destined to an SID so we need to decapsulate it
312				 * and forward it.
313				 */
314				return tail_call_internal(ctx, CILIUM_CALL_SRV6_DECAP, ext_err);
315			}
316		}
