41	static __always_inline
42	int icmp6_send_reply(struct __ctx_buff *ctx, int nh_off, union v6addr new_sip)
43	{
44		union macaddr smac, dmac = CONFIG(interface_mac);
45		const int csum_off = nh_off + ICMP6_CSUM_OFFSET;
46		union v6addr sip, dip;
47		__be32 sum;
48	
49		if (ipv6_load_saddr(ctx, nh_off, &sip) < 0 ||
50		    ipv6_load_daddr(ctx, nh_off, &dip) < 0)
51			return DROP_INVALID;
52	
53		/* ctx->saddr = new_sip */
54		if (ipv6_store_saddr(ctx, new_sip.addr, nh_off) < 0)
55			return DROP_WRITE_ERROR;
56		/* ctx->daddr = ctx->saddr */
57		if (ipv6_store_daddr(ctx, sip.addr, nh_off) < 0)
58			return DROP_WRITE_ERROR;
59	
60		/* fixup checksums */
61		sum = csum_diff(sip.addr, 16, new_sip.addr, 16, 0);
62		if (l4_csum_replace(ctx, csum_off, 0, sum, BPF_F_PSEUDO_HDR) < 0)
63			return DROP_CSUM_L4;
64	
65		sum = csum_diff(dip.addr, 16, sip.addr, 16, 0);
66		if (l4_csum_replace(ctx, csum_off, 0, sum, BPF_F_PSEUDO_HDR) < 0)
67			return DROP_CSUM_L4;
68	
69		/* dmac = smac, smac = dmac */
70		if (eth_load_saddr(ctx, smac.addr, 0) < 0)
71			return DROP_INVALID;
72	
73		if (eth_store_daddr(ctx, smac.addr, 0) < 0 ||
74		    eth_store_saddr(ctx, dmac.addr, 0) < 0)
75			return DROP_WRITE_ERROR;
76	
77		cilium_dbg_capture(ctx, DBG_CAPTURE_DELIVERY, ctx_get_ifindex(ctx));
78	
79		return redirect_self(ctx);
80	}
