82	static __always_inline
83	int icmp6_ndisc_adv_addopt(struct __ctx_buff *ctx)
84	{
85		struct ipv6hdr *ip6;
86		void *data, *data_end;
87		__u64 *opt;
88	
89		if (ctx_change_tail(ctx, (__u32)(ctx_full_len(ctx) + ICMP6_ND_OPT_LEN), 0) < 0)
90			return DROP_INVALID;
91	
92		if (!revalidate_data(ctx, &data, &data_end, &ip6))
93			return DROP_INVALID;
94	
95		ip6->payload_len = bpf_htons(bpf_ntohs(ip6->payload_len)
96								+ ICMP6_ND_OPT_LEN);
97	
98		/* 0 options pkt to make sure csum is additive when read old_opts */
99		opt = (__u64 *)((void *)(ip6 + 1) + sizeof(struct icmp6hdr)
100								+ sizeof(union v6addr));
101		if ((void *)(opt + 1) > data_end)
102			return DROP_INVALID;
103		*opt = 0x0ULL;
104	
105		return 0;
106	}
