108	/*
109	 * icmp6_send_ndisc_adv
110	 * @ctx:	socket buffer
111	 * @nh_off:	offset to the IPv6 header
112	 * @mac:	device mac address
113	 * @to_router:	ndisc is sent to router, otherwise ndisc is sent to an endpoint.
114	 *
115	 * Send an ICMPv6 nadv reply in return to an ICMPv6 ndisc.
116	 */
117	static __always_inline
118	int icmp6_send_ndisc_adv(struct __ctx_buff *ctx, int nh_off,
119				 const union macaddr *mac, bool to_router)
120	{
121		struct icmp6hdr icmp6hdr __align_stack_8 = {}, icmp6hdr_old __align_stack_8;
122		__u8 opts[8], opts_old[8];
123		const int csum_off = nh_off + ICMP6_CSUM_OFFSET;
124		union v6addr target_ip;
125		__be32 sum = 0;
126	
127		/*
128		 * According to RFC4861, sections 4.3 and 7.2.2 unicast neighbour
129		 * solicitations (reachability check) SHOULD but are NOT REQUIRED to
130		 * include the SRC_LL_ADDR option in the NS message.
131		 *
132		 * Likewise, neighbour solicitations during Duplicate Address Detection
133		 * (DAD, RFC4862), SRC_LL_ADDR option must not present.
134		 *
135		 * make room (Type+Length + MAC addr = 8 byte) and 0 it to make sure
136		 * csum is additive.
137		 */
138		if (ctx_load_bytes(ctx, nh_off + ICMP6_ND_OPTS, opts_old,
139				   sizeof(opts_old)) < 0) {
140			__be32 plen_old = 0;
141			__be32 plen = bpf_htonl(8);
142	
143			if (icmp6_ndisc_adv_addopt(ctx) < 0)
144				return DROP_INVALID;
145	
146			/* Account for the pseudoheader change in payload length */
147			sum = csum_diff(&plen_old, sizeof(__be32), &plen,
148					sizeof(__be32), 0);
149		}
150	
151		if (ctx_load_bytes(ctx, nh_off + sizeof(struct ipv6hdr), &icmp6hdr_old,
152				   sizeof(icmp6hdr_old)) < 0)
153			return DROP_INVALID;
154	
155		/* fill icmp6hdr */
156		icmp6hdr.icmp6_type = ICMP6_NA_MSG_TYPE;
157		icmp6hdr.icmp6_code = 0;
158		icmp6hdr.icmp6_cksum = icmp6hdr_old.icmp6_cksum;
159		icmp6hdr.icmp6_dataun.un_data32[0] = 0;
160	
161		icmp6hdr.icmp6_solicited = 1;
162		if (to_router) {
163			icmp6hdr.icmp6_router = 1;
164			icmp6hdr.icmp6_override = 0;
165		} else {
166			icmp6hdr.icmp6_router = 0;
167			icmp6hdr.icmp6_override = 1;
168		}
169	
170		/* Get the target IP, so that NA has SRC_IP=TARGET_IP */
171		if (ctx_load_bytes(ctx, nh_off + sizeof(struct ipv6hdr) + sizeof(icmp6hdr),
172				   &target_ip,
173				   sizeof(target_ip)) < 0)
174			return DROP_WRITE_ERROR;
175	
176		if (ctx_store_bytes(ctx, nh_off + sizeof(struct ipv6hdr), &icmp6hdr,
177				    sizeof(icmp6hdr), 0) < 0)
178			return DROP_WRITE_ERROR;
179	
180		/* ICMPv6 header has changed */
181		sum = csum_diff(&icmp6hdr_old, sizeof(icmp6hdr_old), &icmp6hdr,
182				sizeof(icmp6hdr), sum);
183	
184		/* get old options */
185		if (ctx_load_bytes(ctx, nh_off + ICMP6_ND_OPTS, opts_old,
186				   sizeof(opts_old)) < 0)
187			return DROP_INVALID;
188	
189		opts[0] = 2;
190		opts[1] = 1;
191		opts[2] = mac->addr[0];
192		opts[3] = mac->addr[1];
193		opts[4] = mac->addr[2];
194		opts[5] = mac->addr[3];
195		opts[6] = mac->addr[4];
196		opts[7] = mac->addr[5];
197	
198		/* store ND_OPT_TARGET_LL_ADDR option */
199		if (ctx_store_bytes(ctx, nh_off + ICMP6_ND_OPTS, opts, sizeof(opts), 0) < 0)
200			return DROP_WRITE_ERROR;
201	
202		/* Options have changed */
203		sum = csum_diff(opts_old, sizeof(opts_old), opts, sizeof(opts), sum);
204		if (l4_csum_replace(ctx, csum_off, 0, sum, BPF_F_PSEUDO_HDR) < 0)
205			return DROP_CSUM_L4;
206	
207		return icmp6_send_reply(ctx, nh_off, target_ip);
208	}
