+	opts[1] = 1;
+	opts[2] = mac->addr[0];
+	opts[3] = mac->addr[1];
+	opts[4] = mac->addr[2];
+	opts[5] = mac->addr[3];
+	opts[6] = mac->addr[4];
+	opts[7] = mac->addr[5];
