+	/* Options have changed */
+	sum = csum_diff(opts_old, sizeof(opts_old), opts, sizeof(opts), sum);
+	if (l4_csum_replace(ctx, csum_off, 0, sum, BPF_F_PSEUDO_HDR) < 0)
+		return DROP_CSUM_L4;
