+	/* compute checksum with new payload length */
+	sum = csum_diff(NULL, 0, data, payload_len, 0);
+	sum = ipv6_pseudohdr_checksum(ipv6hdr, IPPROTO_ICMPV6, payload_len,
+				      sum);
+	return sum;
+}
