+	/* L3 layers */
+	PKT_LAYER_IPV4,
+	PKT_LAYER_IPV6,
+	PKT_LAYER_ARP,
+
+	/* IPv6 extension headers */
+	PKT_LAYER_IPV6_HOP_BY_HOP,
+	PKT_LAYER_IPV6_ROUTING,
+	PKT_LAYER_IPV6_AUTH,
+	PKT_LAYER_IPV6_DEST,
+	PKT_LAYER_IPV6_FRAGMENT,
+
+	/* L4 layers */
+	PKT_LAYER_TCP,
+	PKT_LAYER_UDP,
+	PKT_LAYER_ICMP,
+	PKT_LAYER_ICMPV6,
+	PKT_LAYER_SCTP,
+	PKT_LAYER_ESP,
+	PKT_LAYER_IGMP,
+
+	/* Tunnel layers */
+	PKT_LAYER_GENEVE,
+	PKT_LAYER_VXLAN,
